import random

def get_user_choice():
    """Get the user's choice as Rock, Paper, or Scissors."""
    while True:
        user_choice = input("Enter 'rock', 'paper', or 'scissors': ").lower()
        if user_choice in ['rock', 'paper', 'scissors']:
            return user_choice
        else:
            print("Invalid input. Please enter 'rock', 'paper', or 'scissors'.")

def get_computer_choice():
    """Get a random computer choice."""
    return random.choice(['rock', 'paper', 'scissors'])

def play_round(user_choice, computer_choice):
    """Play a single round of Rock, Paper, Scissors and determine the winner."""
    if user_choice == computer_choice:
        print("It's a tie!")
    elif (user_choice == 'rock' and computer_choice == 'scissors') or \
         (user_choice == 'scissors' and computer_choice == 'paper') or \
         (user_choice == 'paper' and computer_choice == 'rock'):
        print(f"You win! The computer chose {computer_choice}.")
    else:
        print(f"The computer wins! The computer chose {computer_choice}.")

def play_game():
    """Play multiple rounds of Rock, Paper, Scissors with the user."""
    print("Welcome to Rock, Paper, Scissors!")
    for _ in range(3):
        user_choice = get_user_choice()
        computer_choice = get_computer_choice()
        play_round(user_choice, computer_choice)

if __name__ == "__main__":
    play_game()
```

This program defines three functions: `get_user_choice()`, `get_computer_choice()`, and `play_round()`. The `play_game()` function calls these functions to play multiple rounds of Rock, Paper, Scissors with the user. The program ensures that the user's input is valid and that the computer's choice is random.
